#include <vector>
#include <algorithm>
using namespace std;
void floydWarshall(vector<vector<int>>&d){int V=d.size();for(int k=0;k<V;k++)for(int i=0;i<V;i++)for(int j=0;j<V;j++)if(d[i][k]!=1e9&&d[k][j]!=1e9)d[i][j]=min(d[i][j],d[i][k]+d[k][j]);}
